import { describe, expect, it, vi } from "vitest";

import { CREDENTIAL_VALUE } from "./credential.js";
vi.mock("./runtime-input.js", () => ({
	resolveRuntimeInput: vi.fn(),
}));

import { resolveRuntimeInput } from "./runtime-input.js";
import * as Schema from "./schema.js";
import { Worker } from "./worker.js";
import * as XldbSchema from "./xldb-schema.js";
import { createXldb } from "./xldb.js";

describe("Worker", () => {
	it("declares an XLDB target and emits target-specific sync output", async () => {
		const worker = new Worker();
		const events = createXldb(worker, "events", {
			type: "managed",
			initialTitle: "Events",
			upsertKey: ["tenantId", "externalId"],
			schema: {
				columns: [
					{ name: "tenantId", title: "Tenant ID", type: XldbSchema.text() },
					{ name: "externalId", title: "External ID", type: XldbSchema.text() },
					{ name: "occurredAt", title: "Occurred At", type: XldbSchema.timestamp() },
					{ name: "metadata", title: "Metadata", type: XldbSchema.json() },
					{ name: "tags", title: "Tags", type: XldbSchema.array(XldbSchema.text()) },
					{ name: "scores", title: "Scores", type: XldbSchema.array(XldbSchema.number()) },
					{ name: "flags", title: "Flags", type: XldbSchema.array(XldbSchema.checkbox()) },
					{ name: "dates", title: "Dates", type: XldbSchema.array(XldbSchema.date()) },
					{ name: "times", title: "Times", type: XldbSchema.array(XldbSchema.timestamp()) },
				],
			},
		});

		worker.sync("eventsSync", {
			database: events,
			mode: "incremental",
			execute: async () => ({
				changes: [
					{
						type: "upsert",
						values: {
							tenantId: "tenant_1",
							externalId: "evt_1",
							occurredAt: "2026-07-22T00:00:00Z",
							metadata: { source: "test" },
							tags: ["launch"],
							scores: [42],
							flags: [true],
							dates: ["2026-07-22"],
							times: ["2026-07-22T00:00:00Z"],
						},
					},
					{ type: "delete", key: { tenantId: "tenant_1", externalId: "evt_0" } },
				],
				hasMore: false,
			}),
		});

		expect(worker.manifest.xldbs).toEqual([
			{
				key: "events",
				config: {
					type: "managed",
					initialTitle: "Events",
					upsertKey: ["tenantId", "externalId"],
					schema: {
						columns: [
							{ name: "tenantId", title: "Tenant ID", type: "text" },
							{ name: "externalId", title: "External ID", type: "text" },
							{ name: "occurredAt", title: "Occurred At", type: "timestamp" },
							{ name: "metadata", title: "Metadata", type: "json" },
							{ name: "tags", title: "Tags", type: "array_text" },
							{ name: "scores", title: "Scores", type: "array_number" },
							{ name: "flags", title: "Flags", type: "array_checkbox" },
							{ name: "dates", title: "Dates", type: "array_date" },
							{ name: "times", title: "Times", type: "array_timestamp" },
						],
					},
				},
			},
		]);
		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "sync",
				key: "eventsSync",
				config: {
					target: { type: "xldb", key: "events" },
					mode: "incremental",
					schedule: undefined,
				},
			},
		]);
		await expect(worker.run("eventsSync", {}, { concreteOutput: true })).resolves.toEqual({
			changes: [
				{
					type: "upsert",
					values: {
						tenantId: "tenant_1",
						externalId: "evt_1",
						occurredAt: "2026-07-22T00:00:00Z",
						metadata: { source: "test" },
						tags: ["launch"],
						scores: [42],
						flags: [true],
						dates: ["2026-07-22"],
						times: ["2026-07-22T00:00:00Z"],
					},
				},
				{ type: "delete", key: { tenantId: "tenant_1", externalId: "evt_0" } },
			],
			hasMore: false,
			nextUserContext: undefined,
			nextPacerStates: {},
		});
	});

	it("includes sdkVersion, credentials, databases, and capabilities in manifest", () => {
		const worker = new Worker();
		worker.credential("LINEAR_API_TOKEN", {
			network: [
				{
					domain: "api.linear.com",
					transform: [
						{
							headers: {
								Authorization: `Bearer ${CREDENTIAL_VALUE}`,
							},
						},
					],
				},
			],
		});
		const tasks = worker.database("tasks", {
			type: "managed",
			initialTitle: "Tasks",
			primaryKeyProperty: "Name",
			schema: {
				properties: {
					Name: Schema.title(),
				},
			},
		});

		worker.sync("tasksSync", {
			database: tasks,
			execute: async () => ({
				changes: [],
				hasMore: false,
			}),
		});

		expect(worker.manifest.sdkVersion).toMatch(/^\d+\.\d+\.\d+/);
		expect(worker.manifest.credentials).toEqual([
			{
				key: "LINEAR_API_TOKEN",
				network: [
					{
						domain: "api.linear.com",
						transform: [
							{
								headers: {
									Authorization: "Bearer {{credential}}",
								},
							},
						],
					},
				],
			},
		]);
		expect(worker.manifest.databases).toEqual([
			{
				key: "tasks",
				config: {
					type: "managed",
					initialTitle: "Tasks",
					primaryKeyProperty: "Name",
					schema: {
						properties: {
							Name: { type: "title" },
						},
					},
				},
			},
		]);
		expect(worker.manifest.xldbs).toEqual([]);
		expect(worker.manifest.pacers).toEqual([]);
		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "sync",
				key: "tasksSync",
				config: {
					databaseKey: "tasks",
					primaryKeyProperty: "Name",
					mode: undefined,
					schedule: undefined,
				},
			},
		]);
	});

	it("preserves attached database declarations in the manifest", () => {
		const worker = new Worker();
		worker.database("tasks", {
			type: "attached",
			initialTitle: "Tasks",
			primaryKeyProperty: "Name",
			schema: {
				properties: {
					Name: Schema.title(),
				},
			},
		});

		expect(worker.manifest.databases).toEqual([
			{
				key: "tasks",
				config: {
					type: "attached",
					initialTitle: "Tasks",
					primaryKeyProperty: "Name",
					schema: {
						properties: {
							Name: { type: "title" },
						},
					},
				},
			},
		]);
	});

	it("serializes manual schedules in the manifest", () => {
		const worker = new Worker();
		const tasks = worker.database("tasks", {
			type: "managed",
			initialTitle: "Tasks",
			primaryKeyProperty: "Name",
			schema: {
				properties: {
					Name: Schema.title(),
				},
			},
		});

		worker.sync("tasksBackfill", {
			database: tasks,
			schedule: "manual",
			execute: async () => ({
				changes: [],
				hasMore: false,
			}),
		});

		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "sync",
				key: "tasksBackfill",
				config: {
					databaseKey: "tasks",
					primaryKeyProperty: "Name",
					mode: undefined,
					schedule: {
						type: "manual",
					},
				},
			},
		]);
	});

	it("includes pacers in manifest and links to sync capabilities", () => {
		const worker = new Worker();
		const tasks = worker.database("tasks", {
			type: "managed",
			initialTitle: "Tasks",
			primaryKeyProperty: "Name",
			schema: {
				properties: {
					Name: Schema.title(),
				},
			},
		});

		const _jiraPacer = worker.pacer("jira", {
			allowedRequests: 10,
			intervalMs: 1000,
		});

		worker.sync("jiraBackfill", {
			database: tasks,
			schedule: "manual",
			execute: async () => ({
				changes: [],
				hasMore: false,
			}),
		});

		worker.sync("jiraDelta", {
			database: tasks,
			schedule: "5m",
			execute: async () => ({
				changes: [],
				hasMore: false,
			}),
		});

		expect(worker.manifest.pacers).toEqual([
			{
				key: "jira",
				config: {
					allowedRequests: 10,
					intervalMs: 1000,
				},
			},
		]);
	});

	it("registers a project custom block from a folder path (type defaults to project)", () => {
		const worker = new Worker();

		worker.customBlock("visualBlock", {
			path: "./blocks/visual",
		});

		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "custom_block",
				key: "visualBlock",
				config: {
					source: { type: "project", path: "./blocks/visual" },
					manifest: {
						version: 1,
						dataSources: {},
					},
				},
			},
		]);
	});

	it("carries a project's custom build command and output dir", () => {
		const worker = new Worker();

		worker.customBlock("built", {
			path: "./app",
			command: "npm run build-prod",
			output: "build",
		});

		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "custom_block",
				key: "built",
				config: {
					source: {
						type: "project",
						path: "./app",
						command: "npm run build-prod",
						output: "build",
					},
					manifest: { version: 1, dataSources: {} },
				},
			},
		]);
	});

	it("registers a static custom block served as-is", () => {
		const worker = new Worker();

		worker.customBlock("prebuilt", { type: "static", path: "./dist" });

		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "custom_block",
				key: "prebuilt",
				config: {
					source: { type: "static", path: "./dist" },
					manifest: { version: 1, dataSources: {} },
				},
			},
		]);
	});

	it("carries the author-declared data-source schemas verbatim into the manifest", () => {
		const worker = new Worker();

		worker.customBlock("issueBoard", {
			path: "./blocks/issueBoard",
			dataSources: {
				issues: {
					name: "Issues",
					description: "The team's issues",
					icon: { type: "emoji", emoji: "🐛" },
					properties: {
						title: { name: "Title", type: "title" },
						status: {
							name: "Status",
							description: "Workflow state",
							type: "status",
						},
					},
				},
			},
		});

		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "custom_block",
				key: "issueBoard",
				config: {
					source: { type: "project", path: "./blocks/issueBoard" },
					manifest: {
						version: 1,
						dataSources: {
							issues: {
								name: "Issues",
								description: "The team's issues",
								icon: { type: "emoji", emoji: "🐛" },
								properties: {
									title: { name: "Title", type: "title" },
									status: {
										name: "Status",
										description: "Workflow state",
										type: "status",
									},
								},
							},
						},
					},
				},
			},
		]);
	});

	it("carries a custom block slash command into the manifest", () => {
		const worker = new Worker();

		worker.customBlock("coinFlip", {
			path: "./blocks/coinflip",
			slashCommand: "coinflip",
		});

		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "custom_block",
				key: "coinFlip",
				config: {
					source: { type: "project", path: "./blocks/coinflip" },
					manifest: {
						version: 1,
						slashCommand: "coinflip",
						dataSources: {},
					},
				},
			},
		]);
	});

	it("strips a leading slash from the slash command before carrying it into the manifest", () => {
		const worker = new Worker();

		worker.customBlock("coinFlip", {
			path: "./blocks/coinflip",
			slashCommand: "/coinflip",
		});

		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "custom_block",
				key: "coinFlip",
				config: {
					source: { type: "project", path: "./blocks/coinflip" },
					manifest: {
						version: 1,
						slashCommand: "coinflip",
						dataSources: {},
					},
				},
			},
		]);
	});

	it.each(["//coinflip", "/", "CoinFlip", "coin flip", "-coinflip", ""])(
		"rejects invalid custom block slash command %j",
		(slashCommand) => {
			const worker = new Worker();

			expect(() =>
				worker.customBlock("coinFlip", {
					path: "./blocks/coinflip",
					slashCommand,
				}),
			).toThrow("must be 1-64 lowercase letters");
		},
	);

	it("rejects duplicate custom block slash commands", () => {
		const worker = new Worker();
		worker.customBlock("firstCoinFlip", {
			path: "./blocks/first",
			slashCommand: "coinflip",
		});

		expect(() =>
			worker.customBlock("secondCoinFlip", {
				path: "./blocks/second",
				slashCommand: "coinflip",
			}),
		).toThrow('Custom block slash command "coinflip" is already registered');
	});

	it("rejects duplicate slash commands across slashed and unslashed forms", () => {
		const worker = new Worker();
		worker.customBlock("firstCoinFlip", {
			path: "./blocks/first",
			slashCommand: "coinflip",
		});

		expect(() =>
			worker.customBlock("secondCoinFlip", {
				path: "./blocks/second",
				slashCommand: "/coinflip",
			}),
		).toThrow('Custom block slash command "coinflip" is already registered');
	});

	it("threads a top-level manifest version into the generated manifest", () => {
		const worker = new Worker();

		worker.customBlock("versioned", {
			path: "./blocks/versioned",
			version: 1,
		});

		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "custom_block",
				key: "versioned",
				config: {
					source: { type: "project", path: "./blocks/versioned" },
					manifest: { version: 1, dataSources: {} },
				},
			},
		]);
	});

	it("cannot run a custom block capability", async () => {
		const worker = new Worker();
		worker.customBlock("visualBlock", {
			path: "./blocks/visual",
		});

		await expect(worker.run("visualBlock", {})).rejects.toThrow(
			'Cannot run custom block capability "visualBlock"',
		);
	});

	it("resolves file-backed input for sync capabilities", async () => {
		const worker = new Worker();
		const tasks = worker.database("tasks", {
			type: "managed",
			initialTitle: "Tasks",
			primaryKeyProperty: "Name",
			schema: {
				properties: {
					Name: Schema.title(),
				},
			},
		});
		worker.sync("tasksSync", {
			database: tasks,
			execute: async () => ({
				changes: [],
				hasMore: false,
			}),
		});

		await worker.run("tasksSync", undefined, { concreteOutput: true });

		expect(resolveRuntimeInput).toHaveBeenCalledWith(undefined);
	});

	it("rejects duplicate keys across credentials, databases, pacers, and capabilities", () => {
		const worker = new Worker();
		const db = worker.database("shared-key", {
			type: "managed",
			initialTitle: "Tasks",
			primaryKeyProperty: "Name",
			schema: {
				properties: {
					Name: Schema.title(),
				},
			},
		});

		expect(() =>
			worker.credential("shared-key", {
				network: [
					{
						domain: "api.example.com",
						transform: [
							{
								headers: {
									Authorization: CREDENTIAL_VALUE,
								},
							},
						],
					},
				],
			}),
		).toThrow('Worker item with key "shared-key" already registered');

		expect(() =>
			worker.sync("shared-key", {
				database: db,
				execute: async () => ({
					changes: [],
					hasMore: false,
				}),
			}),
		).toThrow('Worker item with key "shared-key" already registered');
	});

	it("does not reserve a key when registration fails", () => {
		const worker = new Worker();

		expect(() =>
			worker.credential("REUSABLE_KEY", {
				network: [],
			}),
		).toThrow("must declare at least one network rule");

		expect(() =>
			worker.pacer("REUSABLE_KEY", {
				allowedRequests: 10,
				intervalMs: 1_000,
			}),
		).not.toThrow();
	});

	it("rejects credentials that target the same domain and header", () => {
		const worker = new Worker();
		worker.credential("FIRST_TOKEN", {
			network: [
				{
					domain: "api.example.com",
					transform: [{ headers: { Authorization: `Bearer ${CREDENTIAL_VALUE}` } }],
				},
			],
		});

		expect(() =>
			worker.credential("SECOND_TOKEN", {
				network: [
					{
						domain: "API.EXAMPLE.COM",
						transform: [{ headers: { authorization: CREDENTIAL_VALUE } }],
					},
				],
			}),
		).toThrow('conflicts with credential "FIRST_TOKEN"');
	});

	it("limits the number of credential declarations", () => {
		const worker = new Worker();
		for (let index = 0; index < 100; index += 1) {
			worker.credential(`TOKEN_${index}`, {
				network: [
					{
						domain: `api${index}.example.com`,
						transform: [{ headers: { Authorization: CREDENTIAL_VALUE } }],
					},
				],
			});
		}

		expect(() =>
			worker.credential("ONE_TOO_MANY", {
				network: [
					{
						domain: "overflow.example.com",
						transform: [{ headers: { Authorization: CREDENTIAL_VALUE } }],
					},
				],
			}),
		).toThrow("cannot declare more than 100 credentials");
	});

	it("matches the service limit for the credential declaration payload", () => {
		const worker = new Worker();
		for (let index = 0; index < 32; index += 1) {
			worker.credential(`TOKEN_${index}`, {
				network: [
					{
						domain: `api${index}.example.com`,
						transform: [
							{
								headers: {
									Authorization: `${"x".repeat(8_000)}${CREDENTIAL_VALUE}`,
								},
							},
						],
					},
				],
			});
		}

		expect(() =>
			worker.credential("TOKEN_32", {
				network: [
					{
						domain: "api32.example.com",
						transform: [
							{
								headers: {
									Authorization: `${"x".repeat(8_000)}${CREDENTIAL_VALUE}`,
								},
							},
						],
					},
				],
			}),
		).toThrow("credential declarations must be at most 262144 bytes");
	});
});
